/** Instrument Sans Medium, subset from public/fonts/instrument-sans.ttf.
 * SIL Open Font License: public/fonts/OFL-InstrumentSans.txt.
 * Bundled so image rendering works offline and in Cloudflare Workers. */
const MEDIUM =
  "";
export function premiumShareImageFonts(): {
  name: string;
  data: ArrayBuffer;
  weight: 500;
  style: "normal";
}[] {
  const binary = atob(MEDIUM);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return [{ name: "Instrument Sans", data: bytes.buffer, weight: 500, style: "normal" }];
}
